// Scene matching can share the first projection's map with later
// equal-camera draws. An explicit IGNORE group must still keep its
// own current projection (notably CPU-skinned original-pose draws).
const uint32_t projectionGroupIndex = drawData.viewProjTransformGroups[proj.transformsIndex];
const bool originalProjection = drawData.transformGroups[projectionGroupIndex].matrixId == G_EX_ID_IGNORE;
if ((p.prevFrame != nullptr) && workloadMap.mapped && !workload.debuggerCamera.enabled && !originalProjection) {

// Debugger camera.
const bool debuggerCameraApplied = workload.debuggerCamera.enabled &&
    (proj.type == Projection::Type::Perspective) &&
    (workload.debuggerCamera.sceneIndex == sceneIndex);
if (debuggerCameraApplied) {

interop::float4x4 &prevViewProjTransform = drawData.prevViewProjTransforms[proj.transformsIndex];
if (!debuggerCameraApplied &&
    ((prevProjMatrix == nullptr) || (prevViewMatrix == nullptr) || (rigidBody == nullptr))) {
    // The source projection may be a fixed 16.16 combined matrix.
    // Decomposing and recomposing it changes its depth coefficients
    // enough to move distant geometry past the far clip plane.
    // A horizontal aspect change only scales the combined X column.
    viewProjMatrix = drawData.viewProjTransforms[proj.transformsIndex];
    if (projRatioScale != 1.0f) {
        adjustProjectionMatrix(viewProjMatrix, projRatioScale);
    }
    prevViewProjTransform = viewProjMatrix;
}
else {
    // Preserve the fixed-point combined-matrix residual at both
    // endpoints while retaining RT64's camera interpolation.
    viewProjMatrix = hlslpp::mul(viewMatrix, projMatrix);
    prevViewProjTransform = hlslpp::mul(prevViewTransform, prevProjTransform);
    if (!debuggerCameraApplied) {
        const auto &viewProjMap = workloadMap.viewProjections[proj.transformsIndex];
        const DrawData &prevDrawData = p.workloadQueue->workloads[workloadMap.prevWorkloadIndex].drawData;
        interop::float4x4 curSource = drawData.viewProjTransforms[proj.transformsIndex];
        interop::float4x4 prevSource = prevDrawData.viewProjTransforms[viewProjMap.prevTransformIndex];
        adjustProjectionMatrix(curSource, projRatioScale);
        adjustProjectionMatrix(prevSource, projRatioScale);
        interop::float4x4 curProjSource = drawData.projTransforms[proj.transformsIndex];
        interop::float4x4 prevProjSource = *prevProjMatrix;
        adjustProjectionMatrix(curProjSource, projRatioScale);
        adjustProjectionMatrix(prevProjSource, projRatioScale);
        const interop::float4x4 curRecomposed = hlslpp::mul(drawData.viewTransforms[proj.transformsIndex], curProjSource);
        const interop::float4x4 prevRecomposed = hlslpp::mul(*prevViewMatrix, prevProjSource);
        // RT64 skips projection interpolation when the camera's
        // translation and rotation are not interpolated. In that
        // case both composed matrices use the current projection,
        // so the residual must also come from the current frame.
        const bool interpolateProjection = rigidBody->lerpTranslation || rigidBody->lerpRotation;
        for (int row = 0; row < 4; row++) {
            for (int col = 0; col < 4; col++) {
                const float curResidual = curSource[row][col] - curRecomposed[row][col];
                const float prevResidual = prevSource[row][col] - prevRecomposed[row][col];
                viewProjMatrix[row][col] += interpolateProjection
                    ? prevResidual + (curResidual - prevResidual) * p.curFrameWeight : curResidual;
                prevViewProjTransform[row][col] += interpolateProjection
                    ? prevResidual + (curResidual - prevResidual) * p.prevFrameWeight : curResidual;
            }
        }
    }
